// ── SNOWY PLAYGROUND TRAIN — colorful play train, Scottish winter ──

svg += `<defs>
  <linearGradient id="lg-spt" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#1A1A24' : '#7A7A82'}"/>
    <stop offset="40%" stop-color="${isN ? '#22222E' : '#9098A0'}"/>
    <stop offset="100%" stop-color="${isN ? '#2A2A34' : '#B0B4B8'}"/>
  </linearGradient>
  <linearGradient id="lg-spt-loco" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#2A5A6A"/>
    <stop offset="100%" stop-color="#1A3A4A"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-spt)"/>`;

// ── Overcast clouds (layered, Scottish grey) ──
for (let i = 0; i < 10; i++) {
  const ccx = (w * (-0.1) + i * w * 0.14 + mt * 3) % (w + 120) - 60;
  const ccy = h * 0.04 + Math.sin(i * 1.3) * h * 0.04;
  const ccr = 40 + Math.sin(i * 2.1) * 15;
  const cop = isN ? 0.15 : 0.35 + Math.sin(i * 0.7) * 0.1;
  svg += `<ellipse cx="${ccx}" cy="${ccy}" rx="${ccr}" ry="${ccr * 0.35}" fill="${isN ? '#2A2A34' : '#9A9AA0'}" opacity="${cop}"/>`;
  svg += `<ellipse cx="${ccx - ccr * 0.3}" cy="${ccy + 2}" rx="${ccr * 0.6}" ry="${ccr * 0.25}" fill="${isN ? '#2A2A34' : '#A0A0A8'}" opacity="${cop * 0.8}"/>`;
}

// ── SNOWY GROUND ──
// Main snow layer
svg += `<rect x="0" y="${bY - 10}" width="${w}" height="${h - bY + 10}" fill="${sc.ground}"/>`;
// Uneven snow surface
svg += `<path d="M0 ${bY - 8} Q${w * 0.08} ${bY - 14} ${w * 0.15} ${bY - 6} Q${w * 0.25} ${bY - 12} ${w * 0.35} ${bY - 8} Q${w * 0.45} ${bY - 15} ${w * 0.55} ${bY - 5} Q${w * 0.65} ${bY - 12} ${w * 0.75} ${bY - 7} Q${w * 0.85} ${bY - 13} ${w * 0.95} ${bY - 9} L${w} ${bY - 8} L${w} ${bY} L0 ${bY} Z" fill="#F0F4F6" stroke="#D8E0E4" stroke-width="0.5"/>`;

// Green grass patches peeking through snow
const grassPatches = [[w*0.08,bY+8],[w*0.22,bY+15],[w*0.38,bY+5],[w*0.52,bY+18],[w*0.68,bY+12],[w*0.78,bY+22],[w*0.92,bY+8]];
for (let i = 0; i < 7; i++) {
  const gp = grassPatches[i];
  const gw2 = 12 + Math.sin(i * 2.3) * 5;
  svg += `<ellipse cx="${gp[0]}" cy="${gp[1]}" rx="${gw2}" ry="${gw2 * 0.3}" fill="#5A8A4A" opacity="0.4"/>`;
  // Tiny grass blades
  for (let j = 0; j < 3; j++) {
    const gbx = gp[0] - 4 + j * 4;
    const gbsw = Math.sin(mt * 1.2 + i * 0.7 + j * 0.5) * 1;
    svg += `<line x1="${gbx}" y1="${gp[1]}" x2="${gbx + gbsw}" y2="${gp[1] - 3 - Math.sin(j) * 2}" stroke="#4A7A3A" stroke-width="1" stroke-linecap="round" opacity="0.5"/>`;
  }
}

// Snow shadow/depth variations
for (let i = 0; i < 12; i++) {
  const sdx = w * (i / 12);
  const sdy = bY + 5 + Math.sin(i * 1.7) * 8;
  svg += `<ellipse cx="${sdx}" cy="${sdy}" rx="18" ry="4" fill="#D0D8E0" opacity="0.2"/>`;
}

// ═══ THE COLORFUL TOY TRAIN ═══
const trainX = w * 0.55; // center of train
const trainY = bY - 12; // sitting on snow
const carW = 52; // carriage width
const carH = 42; // carriage height
const gap = 6; // gap between carriages

// ── LOCOMOTIVE (rightmost, dark teal with yellow side) ──
const locoX = trainX + carW + gap;
const locoY = trainY;
// Main body
svg += `<rect x="${locoX - carW / 2}" y="${locoY - carH}" width="${carW}" height="${carH}" rx="3" fill="url(#lg-spt-loco)" stroke="#1A2A3A" stroke-width="${ol}"/>`;
// Yellow side panel
svg += `<rect x="${locoX - carW / 2 + 3}" y="${locoY - carH + 8}" width="${carW - 6}" height="${carH * 0.55}" rx="2" fill="#F0C030" stroke="#D0A020" stroke-width="${ol * 0.4}"/>`;
// Colorful zigzag pattern on yellow
const zigColors = ['#FF4466', '#2ABFA0', '#FF8830', '#6A4AFF', '#FFD700'];
for (let i = 0; i < 5; i++) {
  const zx = locoX - carW / 2 + 6 + i * 9;
  const zy = locoY - carH + 12;
  svg += `<polygon points="${zx},${zy} ${zx + 4},${zy + 10} ${zx + 8},${zy}" fill="${zigColors[i]}" opacity="0.75"/>`;
}
// Window (door-like opening)
svg += `<rect x="${locoX - 6}" y="${locoY - carH + 5}" width="12" height="${carH - 12}" rx="2" fill="${isN ? 'rgba(100,180,220,0.3)' : 'rgba(135,206,235,0.4)'}" stroke="#1A3A4A" stroke-width="${ol * 0.5}"/>`;
// Roof with green awning + snow on top
svg += `<path d="M${locoX - carW / 2 - 3} ${locoY - carH} Q${locoX} ${locoY - carH - 8} ${locoX + carW / 2 + 3} ${locoY - carH}" fill="#2A8A4A" stroke="#1A6A3A" stroke-width="${ol * 0.5}"/>`;
// Snow on roof
svg += `<path d="M${locoX - carW / 2 - 2} ${locoY - carH - 1} Q${locoX - carW / 4} ${locoY - carH - 6} ${locoX} ${locoY - carH - 3} Q${locoX + carW / 4} ${locoY - carH - 7} ${locoX + carW / 2 + 2} ${locoY - carH - 1}" fill="#F0F4F6" stroke="none"/>`;
// Roof support poles
svg += `<line x1="${locoX - carW / 2}" y1="${locoY - carH}" x2="${locoX - carW / 2}" y2="${locoY - carH - 5}" stroke="#1A3A4A" stroke-width="2"/>`;
svg += `<line x1="${locoX + carW / 2}" y1="${locoY - carH}" x2="${locoX + carW / 2}" y2="${locoY - carH - 5}" stroke="#1A3A4A" stroke-width="2"/>`;
// Wheels
for (let i = 0; i < 2; i++) {
  const wx = locoX - 14 + i * 28;
  svg += `<circle cx="${wx}" cy="${locoY + 2}" r="6" fill="#333" stroke="#222" stroke-width="${ol * 0.4}"/>`;
  svg += `<circle cx="${wx}" cy="${locoY + 2}" r="3" fill="#555"/>`;
}

// ── MIDDLE CARRIAGE (blue with elephant painting) ──
const midX = trainX;
const midY = trainY;
// Main body
svg += `<rect x="${midX - carW / 2}" y="${midY - carH}" width="${carW}" height="${carH}" rx="3" fill="#3A8ACA" stroke="#2A6AA0" stroke-width="${ol}"/>`;
// Elephant artwork (simplified)
const elX = midX - 8, elY = midY - carH / 2 - 2;
svg += `<circle cx="${elX}" cy="${elY}" r="10" fill="#4ABABA" stroke="#2A8A8A" stroke-width="1.5"/>`;
// Elephant head shape
svg += `<circle cx="${elX + 2}" cy="${elY - 2}" r="6" fill="#5ACACA" stroke="#3AAAA0" stroke-width="1"/>`;
// Trunk
svg += `<path d="M${elX + 6} ${elY} Q${elX + 12} ${elY + 4} ${elX + 10} ${elY + 10}" fill="none" stroke="#3AAAA0" stroke-width="2" stroke-linecap="round"/>`;
// Eye
svg += `<circle cx="${elX + 3}" cy="${elY - 3}" r="1.5" fill="#222"/>`;
// Ear
svg += `<ellipse cx="${elX - 3}" cy="${elY}" rx="4" ry="5" fill="#4ABABA" stroke="#3A9A9A" stroke-width="0.8"/>`;
// Target/bullseye decoration
const tgX = midX + 14, tgY = midY - carH / 2;
svg += `<circle cx="${tgX}" cy="${tgY}" r="8" fill="#FF4466" stroke="#CC2244" stroke-width="1"/>`;
svg += `<circle cx="${tgX}" cy="${tgY}" r="5" fill="#FFF" stroke="#CC2244" stroke-width="0.5"/>`;
svg += `<circle cx="${tgX}" cy="${tgY}" r="2.5" fill="#FF4466"/>`;
// Pink/coral accent strip
svg += `<rect x="${midX - carW / 2}" y="${midY - 8}" width="${carW}" height="8" fill="#FF7088" stroke="#DD5068" stroke-width="${ol * 0.3}"/>`;
// Orange wheel decoration
svg += `<circle cx="${midX + 16}" cy="${midY - 2}" r="5" fill="#FF8830" stroke="#DD6620" stroke-width="1"/>`;
svg += `<circle cx="${midX + 16}" cy="${midY - 2}" r="2" fill="#FFB060"/>`;
// Snow on top
svg += `<ellipse cx="${midX}" cy="${midY - carH - 1}" rx="${carW / 2 + 2}" ry="4" fill="#F0F4F6"/>`;
// Wheels
for (let i = 0; i < 2; i++) {
  const wx = midX - 14 + i * 28;
  svg += `<circle cx="${wx}" cy="${midY + 2}" r="6" fill="#333" stroke="#222" stroke-width="${ol * 0.4}"/>`;
  svg += `<circle cx="${wx}" cy="${midY + 2}" r="3" fill="#555"/>`;
}

// ── BACK CARRIAGE (orange/yellow, far left) ──
const backX = trainX - carW - gap;
const backY = trainY;
svg += `<rect x="${backX - carW / 2}" y="${backY - carH}" width="${carW}" height="${carH}" rx="3" fill="#E0882A" stroke="#C06A1A" stroke-width="${ol}"/>`;
// Colorful geometric patterns
for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 2; j++) {
    const px = backX - carW / 2 + 6 + i * 16;
    const py = backY - carH + 6 + j * 18;
    const pCols = ['#FF4466', '#2ABFA0', '#FFD700', '#6A4AFF', '#FF8830', '#4A9ADA'];
    svg += `<rect x="${px}" y="${py}" width="10" height="12" rx="2" fill="${pCols[(i + j * 3) % 6]}" opacity="0.7"/>`;
  }
}
// Green canopy element
svg += `<path d="M${backX - 10} ${backY - carH - 2} Q${backX} ${backY - carH - 10} ${backX + 12} ${backY - carH - 2}" fill="#3A9A4A" stroke="#2A7A3A" stroke-width="1"/>`;
// Snow
svg += `<ellipse cx="${backX}" cy="${backY - carH - 1}" rx="${carW / 2 + 2}" ry="3.5" fill="#F0F4F6"/>`;
// Wheels
for (let i = 0; i < 2; i++) {
  const wx = backX - 14 + i * 28;
  svg += `<circle cx="${wx}" cy="${backY + 2}" r="6" fill="#333" stroke="#222" stroke-width="${ol * 0.4}"/>`;
  svg += `<circle cx="${wx}" cy="${backY + 2}" r="3" fill="#555"/>`;
}

// ── Coupling bars between carriages ──
svg += `<line x1="${backX + carW / 2}" y1="${backY - 5}" x2="${midX - carW / 2}" y2="${midY - 5}" stroke="#555" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${midX + carW / 2}" y1="${midY - 5}" x2="${locoX - carW / 2}" y2="${locoY - 5}" stroke="#555" stroke-width="2" stroke-linecap="round"/>`;

// ── Wooden base/platform under train ──
svg += `<rect x="${backX - carW / 2 - 5}" y="${trainY + 5}" width="${(carW + gap) * 3 + 10}" height="5" rx="1" fill="#8B7355" stroke="#6B5335" stroke-width="${ol * 0.3}"/>`;

// ═══ BARE WINTER TREES ═══
const treePoss = [[w * 0.05, 70], [w * 0.15, 55], [w * 0.88, 65], [w * 0.95, 50], [w * 0.42, 45], [w * 0.75, 40]];
for (let t = 0; t < 6; t++) {
  const ttx = treePoss[t][0];
  const tth = treePoss[t][1];
  const tsw = Math.sin(mt * 0.4 + t * 1.2) * 1.5;
  // Scale: further trees are smaller
  const scale = t < 4 ? 1 : 0.7;
  // Trunk
  svg += `<path d="M${ttx - 2 * scale} ${bY - 3} Q${ttx + tsw * 0.3} ${bY - tth * 0.5 * scale} ${ttx + tsw} ${bY - tth * scale}" fill="none" stroke="#4A3828" stroke-width="${4 * scale}" stroke-linecap="round"/>`;
  // Bare branches
  for (let b = 0; b < 4; b++) {
    const bh = bY - tth * scale * (0.5 + b * 0.15);
    const bDir = (b % 2 === 0 ? 1 : -1);
    const bLen = (12 + Math.sin(b * 2.7) * 6) * scale;
    const bsw = Math.sin(mt * 0.6 + t * 0.9 + b * 0.7) * 2;
    svg += `<path d="M${ttx + tsw * (0.5 + b * 0.15)} ${bh} Q${ttx + bDir * bLen * 0.6 + bsw} ${bh - 5 * scale} ${ttx + bDir * bLen + bsw} ${bh - 8 * scale}" fill="none" stroke="#4A3828" stroke-width="${2 * scale}" stroke-linecap="round"/>`;
    // Sub-branches
    svg += `<line x1="${ttx + bDir * bLen * 0.5 + bsw}" y1="${bh - 3 * scale}" x2="${ttx + bDir * bLen * 0.7 + bsw}" y2="${bh - 12 * scale}" stroke="#5A4838" stroke-width="${1 * scale}" stroke-linecap="round"/>`;
  }
}

// ── Far background: fence/sports field ──
const fenceY = bY - 25;
svg += `<line x1="0" y1="${fenceY}" x2="${w}" y2="${fenceY}" stroke="#8A8A8A" stroke-width="0.8" opacity="0.25"/>`;
for (let i = 0; i < 25; i++) {
  const fx = i * (w / 25);
  svg += `<line x1="${fx}" y1="${fenceY}" x2="${fx}" y2="${fenceY - 8}" stroke="#8A8A8A" stroke-width="0.5" opacity="0.2"/>`;
}

// ── Far tree line (silhouette, very distant) ──
for (let i = 0; i < 15; i++) {
  const ftx = w * (i / 15);
  const fth = 12 + Math.sin(i * 1.9) * 5;
  svg += `<circle cx="${ftx}" cy="${fenceY - fth}" r="${fth * 0.6}" fill="${isN ? '#1A2A1A' : '#6A7A6A'}" opacity="0.2"/>`;
}

// ── Other playground equipment (far left, silhouette) ──
const peX = w * 0.02, peY = bY - 8;
// Distant play structure
svg += `<rect x="${peX}" y="${peY - 25}" width="20" height="25" rx="2" fill="#D08020" stroke="#A06010" stroke-width="${ol * 0.4}" opacity="0.5"/>`;
svg += `<ellipse cx="${peX + 10}" cy="${peY - 26}" rx="13" ry="3" fill="#F0F4F6" opacity="0.5"/>`;

// ── Mushroom/dome play equipment (far right) ──
const meX = w * 0.98, meY = bY - 5;
svg += `<ellipse cx="${meX}" cy="${meY - 8}" rx="10" ry="8" fill="#8A8A90" stroke="#6A6A70" stroke-width="${ol * 0.3}" opacity="0.4"/>`;
svg += `<ellipse cx="${meX}" cy="${meY - 9}" rx="10" ry="3" fill="#F0F4F6" opacity="0.4"/>`;

// ═══ SMALL FOOTPRINTS in snow (leading toward the train) ═══
for (let i = 0; i < 8; i++) {
  const fpx = w * 0.2 + i * w * 0.04 + Math.sin(i * 0.8) * 4;
  const fpy = bY + 8 + Math.sin(i * 1.1) * 3;
  svg += `<ellipse cx="${fpx}" cy="${fpy}" rx="2.5" ry="3.5" fill="#C8D0D8" opacity="0.35" transform="rotate(${10 + Math.sin(i) * 8} ${fpx} ${fpy})"/>`;
}

// ═══ ANIMATED SNOWFLAKES ═══
for (let i = 0; i < 30; i++) {
  const sfx = (Math.sin(i * 73.1 + 5.3) * 0.5 + 0.5) * w + Math.sin(mt * 0.5 + i * 0.4) * 12;
  const sfy = ((mt * 5 + i * (h / 30)) % (h + 20)) - 10;
  const sfr = 1.2 + Math.sin(i * 2.3) * 0.7;
  const sfop = 0.3 + Math.sin(mt * 1.5 + i * 0.7) * 0.2;
  svg += `<circle cx="${sfx % w}" cy="${sfy}" r="${sfr}" fill="#FFF" opacity="${sfop}"/>`;
}
// Larger, slower snowflakes (foreground)
for (let i = 0; i < 8; i++) {
  const lfx = (Math.sin(i * 41.7 + 2.1) * 0.5 + 0.5) * w + Math.sin(mt * 0.3 + i * 0.8) * 20;
  const lfy = ((mt * 3 + i * (h / 8)) % (h + 30)) - 15;
  const lfr = 2 + Math.sin(i * 1.7) * 1;
  svg += `<circle cx="${lfx % w}" cy="${lfy}" r="${lfr}" fill="#FFF" opacity="${0.4 + Math.sin(mt * 1.2 + i) * 0.2}"/>`;
}

// ═══ SNOW SPARKLES on ground ═══
for (let i = 0; i < 15; i++) {
  const skx = w * (0.05 + i * 0.06);
  const sky2 = bY - 5 + Math.sin(i * 2.3) * 8;
  const skop = 0.15 + Math.sin(mt * 2.5 + i * 1.3) * 0.15;
  svg += `<circle cx="${skx}" cy="${sky2}" r="1" fill="#FFF" opacity="${skop}"/>`;
}

// ── Soft winter light (no sun visible, diffused) ──
if (!isN) {
  // Diffused light glow through clouds
  svg += `<ellipse cx="${w * 0.6}" cy="${h * 0.08}" rx="${w * 0.2}" ry="${h * 0.06}" fill="#FFF" opacity="0.04"/>`;
} else {
  // Night: distant street lamp glow
  const slx = w * 0.92;
  svg += `<line x1="${slx}" y1="${bY}" x2="${slx}" y2="${bY - 45}" stroke="#5A5A5A" stroke-width="2"/>`;
  svg += `<circle cx="${slx}" cy="${bY - 48}" r="4" fill="#FFE088" opacity="0.7"/>`;
  svg += `<circle cx="${slx}" cy="${bY - 48}" r="25" fill="#FFE088" opacity="0.04"/>`;
  // Stars peeking through clouds
  for (let i = 0; i < 12; i++) {
    const stx = (Math.sin(i * 93.7 + 2.1) * 0.5 + 0.5) * w;
    const sty2 = (Math.sin(i * 217.3 + 5.7) * 0.5 + 0.5) * h * 0.25;
    const strop = 0.15 + Math.sin(mt * 1.5 + i * 0.6) * 0.15;
    svg += `<circle cx="${stx}" cy="${sty2}" r="0.6" fill="#FFF" opacity="${strop}"/>`;
  }
}
